/**
 * demoIW service worker.
 *
 * Hand-rolled rather than generated by next-pwa — see ADR-010. The policy is
 * deliberately narrow: make the app installable and survive a dropped
 * connection, without ever serving stale business data.
 *
 * Bump CACHE_VERSION whenever PRECACHE_URLS changes; the activate handler
 * deletes every cache that is not the current version.
 */
const CACHE_VERSION = 'demoiw-v1'

/**
 * Precache only assets that are certain to exist. `cache.addAll` is atomic —
 * a single 404 rejects the whole call and leaves the app with no precache at
 * all — and live routes such as `/` or `/cases` are deliberately excluded so a
 * stale dashboard can never be served as if it were fresh.
 */
const PRECACHE_URLS = [
  '/offline',
  '/en/offline',
  '/manifest.json',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/apple-touch-icon.png',
]

const STATIC_ASSET_PREFIXES = ['/_next/static/', '/icons/']
const STATIC_ASSET_EXTENSIONS = ['.css', '.js', '.png', '.svg', '.ico', '.webp', '.woff2']

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE_VERSION)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      .then(() => self.skipWaiting()),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) =>
        Promise.all(
          names.filter((name) => name !== CACHE_VERSION).map((name) => caches.delete(name)),
        ),
      )
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('fetch', (event) => {
  const request = event.request

  // Never intercept writes, cross-origin traffic, or the API. Cached business
  // data during a demo is worse than no data at all.
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith('/api/')) return

  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request))
    return
  }

  if (isStaticAsset(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request))
  }
})

/**
 * Navigations always try the network, so the operator sees live data. Only when
 * the network throws do we reach for the cache, and then for the offline page.
 */
async function networkFirst(request) {
  try {
    return await fetch(request)
  } catch (error) {
    const cache = await caches.open(CACHE_VERSION)
    const cached = await cache.match(request)
    if (cached) return cached

    const fallback = await cache.match(offlineUrlFor(new URL(request.url).pathname))
    if (fallback) return fallback
    throw error
  }
}

/**
 * Static assets are content-hashed or stable, so serving the cached copy first
 * is safe; the background refresh keeps the next load current.
 */
async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE_VERSION)
  const cached = await cache.match(request)

  const refresh = fetch(request)
    .then((response) => {
      cache.put(request, response)
      return response
    })
    .catch(() => cached)

  return cached ?? refresh
}

/**
 * The worker cannot run next-intl. Routing uses `localePrefix: 'as-needed'`, so
 * Spanish (the default locale) is unprefixed and English is the only prefixed
 * locale — checking for the `/en` segment is sufficient for these two locales
 * and is not a general negotiation mechanism. Adding a third locale means
 * revisiting this function.
 */
function offlineUrlFor(pathname) {
  return pathname === '/en' || pathname.startsWith('/en/') ? '/en/offline' : '/offline'
}

function isStaticAsset(pathname) {
  return (
    STATIC_ASSET_PREFIXES.some((prefix) => pathname.startsWith(prefix)) ||
    STATIC_ASSET_EXTENSIONS.some((extension) => pathname.endsWith(extension))
  )
}
